/**
 * Emits the marketing site's inline organism `<defs>` plus per-alias
 * family/hue assignments, generated by the real `organisms.ts` pipeline so
 * the site shows exactly what those coves would grow in the app.
 * Run: bun run scripts/emit-site-organisms.ts
 */
import {
  FAMILIES,
  LIVING_FAMILIES,
  generateFamily,
  organismFor,
  type OrganismPath,
} from "../src/components/organisms";
import { spaceColor } from "../src/components/spaceColor";

function pathsToMarkup(paths: readonly OrganismPath[]): string {
  return paths
    .map((p) =>
      p.stroke !== undefined
        ? `<path d="${p.d}" fill="none" stroke="currentColor" stroke-width="${p.stroke}" stroke-linecap="round" stroke-linejoin="round"/>`
        : `<path d="${p.d}" fill="currentColor"${p.evenodd ? ' fill-rule="evenodd"' : ""}/>`,
    )
    .join("");
}

/** Seeds for the marketing page's randomised circle pool. */
const POOL_SEEDS: Record<string, number> = {
  sunAnemone: 34, tubes: 5, staghorn: 2, flower: 1,
  scallop: 2, spiral: 3, bubbles: 1, seagrass: 2,
};

/** One hand-picked seed per family for the seabed strip. */
const STRIP_SEEDS: Record<string, number> = {
  sunAnemone: 1, tubes: 5, staghorn: 2, brain: 8, flower: 1, scallop: 2,
  spiral: 3, bubbles: 1, seagrass: 2, shell: 5, nudibranch: 3,
};

// o-coral is NOT emitted: the brand mark is the traced fan coral, which
// lives verbatim in site/index.html's defs (copied from ReefMark.tsx) and
// only ever appears in brand positions (nav, lockup) — never as a cove
// glyph or a strip organism.
for (const fam of FAMILIES) {
  const org = generateFamily(fam, STRIP_SEEDS[fam]!);
  console.log(`<g id="o-${fam}">${pathsToMarkup(org.paths)}</g>`);
}
// a second sun anemone individual — the strip's centerpiece
console.log(`<g id="o-anemone-b">${pathsToMarkup(generateFamily("sunAnemone", 34).paths)}</g>`);

const HUE_VARS: Record<string, string> = {
  "#f59e0b": "--amber", "#6366f1": "--indigo", "#ec4899": "--pink",
  "#0284c7": "--sky", "#84cc16": "--lime", "#8b5cf6": "--violet",
  "#f97316": "--orange", "#0d9488": "--seafoam",
};

console.log("\n# circle aliases (family / hue var / def markup):");
for (const alias of ["household", "schoolrun", "accountant", "japan", "personal"]) {
  const org = organismFor(alias);
  const hue = spaceColor(alias);
  console.log(`## ${alias}: ${org.family} ${HUE_VARS[hue.base] ?? hue.base}`);
  console.log(`<g id="o-cove-${alias}">${pathsToMarkup(org.paths)}</g>`);
}

// The marketing page's five cove circles are dealt at load from this pool,
// so a visitor sees a different reef each time. One individual per *living*
// family: the retired plans remap onto survivors, so including them would
// deal the same body twice under two names and break the "all different"
// guarantee the picker relies on.
console.log("\n# randomised circle pool (id / family):");
for (const fam of LIVING_FAMILIES) {
  const org = generateFamily(fam, POOL_SEEDS[fam] ?? 1);
  console.log(`## ${fam}`);
  console.log(`<g id="o-pool-${fam}">${pathsToMarkup(org.paths)}</g>`);
}
